-- Упражнения книги 19, глава 21 (Администрирование Linux). Файл строит автор-скрипт (не в репозитории); после правок можно редактировать и вручную.

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 21, 'la21-lvs-sizes', 0, 'func', 'Активные тома из lvs JSON', 'Команда lvs --reportformat json печатает объект с массивом "report"; каждый элемент массива — объект, в котором массив "lv" (может отсутствовать) хранит строки таблицы, а все значения в строках — строки. Напишите функцию active_sizes(text, vg): text — вывод команды, vg — имя группы. Верните словарь имя тома → размер в мебибайтах (целое число) для томов группы vg, которые активны (в lv_attr не короче пяти символов, пятый символ равен "a") и не скрыты (имя не начинается с "["). Размер lv_size — число с точкой, перед которым может стоять "<" (его игнорируют), и необязательный суффикс из k, m, g, t, p: степени 1024 (k — КиБ, m — МиБ и так далее). Без суффикса число означает байты. Результат округляйте до ближайшего целого, половину — вверх. Рассматривайте все элементы "report".', 'def active_sizes(text, vg):
    pass
', 'json.loads, затем два вложенных цикла. Размер: Fraction(число) * множитель / 1024**2, округление — int(x + Fraction(1, 2)).', '{"func": "active_sizes", "tests": [{"args": ["{\n      \"report\": [\n          {\n              \"lv\": [\n                  {\"lv_name\":\"root\", \"vg_name\":\"rhel\", \"lv_attr\":\"-wi-ao----\", \"lv_size\":\"<17.00g\", \"pool_lv\":\"\", \"origin\":\"\", \"data_percent\":\"\", \"metadata_percent\":\"\", \"move_pv\":\"\", \"mirror_log\":\"\", \"copy_percent\":\"\", \"convert_lv\":\"\"},\n                  {\"lv_name\":\"swap\", \"vg_name\":\"rhel\", \"lv_attr\":\"-wi-ao----\", \"lv_size\":\"2.00g\", \"pool_lv\":\"\", \"origin\":\"\", \"data_percent\":\"\", \"metadata_percent\":\"\", \"move_pv\":\"\", \"mirror_log\":\"\", \"copy_percent\":\"\", \"convert_lv\":\"\"},\n                  {\"lv_name\":\"scratch\", \"vg_name\":\"rhel\", \"lv_attr\":\"-wi-------\", \"lv_size\":\"5.00g\", \"pool_lv\":\"\", \"origin\":\"\", \"data_percent\":\"\", \"metadata_percent\":\"\", \"move_pv\":\"\", \"mirror_log\":\"\", \"copy_percent\":\"\", \"convert_lv\":\"\"},\n                  {\"lv_name\":\"[lvol0_pmspare]\", \"vg_name\":\"rhel\", \"lv_attr\":\"ewi-------\", \"lv_size\":\"<120.00m\", \"pool_lv\":\"\", \"origin\":\"\", \"data_percent\":\"\", \"metadata_percent\":\"\", \"move_pv\":\"\", \"mirror_log\":\"\", \"copy_percent\":\"\", \"convert_lv\":\"\"},\n                  {\"lv_name\":\"data\", \"vg_name\":\"datavg\", \"lv_attr\":\"-wi-ao----\", \"lv_size\":\"100.00g\", \"pool_lv\":\"\", \"origin\":\"\", \"data_percent\":\"\", \"metadata_percent\":\"\", \"move_pv\":\"\", \"mirror_log\":\"\", \"copy_percent\":\"\", \"convert_lv\":\"\"}\n              ]\n          }\n      ]\n  }\n", "rhel"], "expected": {"root": 17408, "swap": 2048}}, {"args": ["{\n      \"report\": [\n          {\n              \"lv\": [\n                  {\"lv_name\":\"root\", \"vg_name\":\"rhel\", \"lv_attr\":\"-wi-ao----\", \"lv_size\":\"<17.00g\", \"pool_lv\":\"\", \"origin\":\"\", \"data_percent\":\"\", \"metadata_percent\":\"\", \"move_pv\":\"\", \"mirror_log\":\"\", \"copy_percent\":\"\", \"convert_lv\":\"\"},\n                  {\"lv_name\":\"swap\", \"vg_name\":\"rhel\", \"lv_attr\":\"-wi-ao----\", \"lv_size\":\"2.00g\", \"pool_lv\":\"\", \"origin\":\"\", \"data_percent\":\"\", \"metadata_percent\":\"\", \"move_pv\":\"\", \"mirror_log\":\"\", \"copy_percent\":\"\", \"convert_lv\":\"\"},\n                  {\"lv_name\":\"scratch\", \"vg_name\":\"rhel\", \"lv_attr\":\"-wi-------\", \"lv_size\":\"5.00g\", \"pool_lv\":\"\", \"origin\":\"\", \"data_percent\":\"\", \"metadata_percent\":\"\", \"move_pv\":\"\", \"mirror_log\":\"\", \"copy_percent\":\"\", \"convert_lv\":\"\"},\n                  {\"lv_name\":\"[lvol0_pmspare]\", \"vg_name\":\"rhel\", \"lv_attr\":\"ewi-------\", \"lv_size\":\"<120.00m\", \"pool_lv\":\"\", \"origin\":\"\", \"data_percent\":\"\", \"metadata_percent\":\"\", \"move_pv\":\"\", \"mirror_log\":\"\", \"copy_percent\":\"\", \"convert_lv\":\"\"},\n                  {\"lv_name\":\"data\", \"vg_name\":\"datavg\", \"lv_attr\":\"-wi-ao----\", \"lv_size\":\"100.00g\", \"pool_lv\":\"\", \"origin\":\"\", \"data_percent\":\"\", \"metadata_percent\":\"\", \"move_pv\":\"\", \"mirror_log\":\"\", \"copy_percent\":\"\", \"convert_lv\":\"\"}\n              ]\n          }\n      ]\n  }\n", "datavg"], "expected": {"data": 102400}}, {"args": ["{\n      \"report\": [\n          {\n              \"lv\": [\n                  {\"lv_name\":\"root\", \"vg_name\":\"rhel\", \"lv_attr\":\"-wi-ao----\", \"lv_size\":\"<17.00g\", \"pool_lv\":\"\", \"origin\":\"\", \"data_percent\":\"\", \"metadata_percent\":\"\", \"move_pv\":\"\", \"mirror_log\":\"\", \"copy_percent\":\"\", \"convert_lv\":\"\"},\n                  {\"lv_name\":\"swap\", \"vg_name\":\"rhel\", \"lv_attr\":\"-wi-ao----\", \"lv_size\":\"2.00g\", \"pool_lv\":\"\", \"origin\":\"\", \"data_percent\":\"\", \"metadata_percent\":\"\", \"move_pv\":\"\", \"mirror_log\":\"\", \"copy_percent\":\"\", \"convert_lv\":\"\"},\n                  {\"lv_name\":\"scratch\", \"vg_name\":\"rhel\", \"lv_attr\":\"-wi-------\", \"lv_size\":\"5.00g\", \"pool_lv\":\"\", \"origin\":\"\", \"data_percent\":\"\", \"metadata_percent\":\"\", \"move_pv\":\"\", \"mirror_log\":\"\", \"copy_percent\":\"\", \"convert_lv\":\"\"},\n                  {\"lv_name\":\"[lvol0_pmspare]\", \"vg_name\":\"rhel\", \"lv_attr\":\"ewi-------\", \"lv_size\":\"<120.00m\", \"pool_lv\":\"\", \"origin\":\"\", \"data_percent\":\"\", \"metadata_percent\":\"\", \"move_pv\":\"\", \"mirror_log\":\"\", \"copy_percent\":\"\", \"convert_lv\":\"\"},\n                  {\"lv_name\":\"data\", \"vg_name\":\"datavg\", \"lv_attr\":\"-wi-ao----\", \"lv_size\":\"100.00g\", \"pool_lv\":\"\", \"origin\":\"\", \"data_percent\":\"\", \"metadata_percent\":\"\", \"move_pv\":\"\", \"mirror_log\":\"\", \"copy_percent\":\"\", \"convert_lv\":\"\"}\n              ]\n          }\n      ]\n  }\n", "nosuch"], "expected": {}}, {"args": ["{\n      \"report\": [\n          {\n              \"lv\": [\n                  {\"lv_name\":\"a\", \"vg_name\":\"vg0\", \"lv_attr\":\"-wi-a-----\", \"lv_size\":\"10737418240\", \"pool_lv\":\"\", \"origin\":\"\", \"data_percent\":\"\", \"metadata_percent\":\"\", \"move_pv\":\"\", \"mirror_log\":\"\", \"copy_percent\":\"\", \"convert_lv\":\"\"},\n                  {\"lv_name\":\"b\", \"vg_name\":\"vg0\", \"lv_attr\":\"-wi-a-----\", \"lv_size\":\"536870912\", \"pool_lv\":\"\", \"origin\":\"\", \"data_percent\":\"\", \"metadata_percent\":\"\", \"move_pv\":\"\", \"mirror_log\":\"\", \"copy_percent\":\"\", \"convert_lv\":\"\"},\n                  {\"lv_name\":\"c\", \"vg_name\":\"vg0\", \"lv_attr\":\"-wi-a-----\", \"lv_size\":\"524288\", \"pool_lv\":\"\", \"origin\":\"\", \"data_percent\":\"\", \"metadata_percent\":\"\", \"move_pv\":\"\", \"mirror_log\":\"\", \"copy_percent\":\"\", \"convert_lv\":\"\"},\n                  {\"lv_name\":\"d\", \"vg_name\":\"vg0\", \"lv_attr\":\"-wi-a-----\", \"lv_size\":\"524287\", \"pool_lv\":\"\", \"origin\":\"\", \"data_percent\":\"\", \"metadata_percent\":\"\", \"move_pv\":\"\", \"mirror_log\":\"\", \"copy_percent\":\"\", \"convert_lv\":\"\"},\n                  {\"lv_name\":\"e\", \"vg_name\":\"vg0\", \"lv_attr\":\"-wi-a-----\", \"lv_size\":\"1048575\", \"pool_lv\":\"\", \"origin\":\"\", \"data_percent\":\"\", \"metadata_percent\":\"\", \"move_pv\":\"\", \"mirror_log\":\"\", \"copy_percent\":\"\", \"convert_lv\":\"\"}\n              ]\n          }\n      ]\n  }\n", "vg0"], "expected": {"a": 10240, "b": 512, "c": 1, "d": 0, "e": 1}}, {"args": ["{\n      \"report\": [\n          {\n              \"lv\": [\n                  {\"lv_name\":\"big\", \"vg_name\":\"vg0\", \"lv_attr\":\"-wi-a-----\", \"lv_size\":\"1.50t\", \"pool_lv\":\"\", \"origin\":\"\", \"data_percent\":\"\", \"metadata_percent\":\"\", \"move_pv\":\"\", \"mirror_log\":\"\", \"copy_percent\":\"\", \"convert_lv\":\"\"},\n                  {\"lv_name\":\"tiny\", \"vg_name\":\"vg0\", \"lv_attr\":\"-wi-a-----\", \"lv_size\":\"512.00k\", \"pool_lv\":\"\", \"origin\":\"\", \"data_percent\":\"\", \"metadata_percent\":\"\", \"move_pv\":\"\", \"mirror_log\":\"\", \"copy_percent\":\"\", \"convert_lv\":\"\"},\n                  {\"lv_name\":\"sm\", \"vg_name\":\"vg0\", \"lv_attr\":\"-wi-a-----\", \"lv_size\":\"<4.00k\", \"pool_lv\":\"\", \"origin\":\"\", \"data_percent\":\"\", \"metadata_percent\":\"\", \"move_pv\":\"\", \"mirror_log\":\"\", \"copy_percent\":\"\", \"convert_lv\":\"\"},\n                  {\"lv_name\":\"pool\", \"vg_name\":\"vg0\", \"lv_attr\":\"twi-aotz--\", \"lv_size\":\"93.13g\", \"pool_lv\":\"\", \"origin\":\"\", \"data_percent\":\"12.50\", \"metadata_percent\":\"3.10\", \"move_pv\":\"\", \"mirror_log\":\"\", \"copy_percent\":\"\", \"convert_lv\":\"\"},\n                  {\"lv_name\":\"[pool_tdata]\", \"vg_name\":\"vg0\", \"lv_attr\":\"Twi-ao----\", \"lv_size\":\"93.13g\", \"pool_lv\":\"\", \"origin\":\"\", \"data_percent\":\"\", \"metadata_percent\":\"\", \"move_pv\":\"\", \"mirror_log\":\"\", \"copy_percent\":\"\", \"convert_lv\":\"\"},\n                  {\"lv_name\":\"[pool_tmeta]\", \"vg_name\":\"vg0\", \"lv_attr\":\"ewi-ao----\", \"lv_size\":\"<96.00m\", \"pool_lv\":\"\", \"origin\":\"\", \"data_percent\":\"\", \"metadata_percent\":\"\", \"move_pv\":\"\", \"mirror_log\":\"\", \"copy_percent\":\"\", \"convert_lv\":\"\"},\n                  {\"lv_name\":\"susp\", \"vg_name\":\"vg0\", \"lv_attr\":\"-wi-s-----\", \"lv_size\":\"1.00g\", \"pool_lv\":\"\", \"origin\":\"\", \"data_percent\":\"\", \"metadata_percent\":\"\", \"move_pv\":\"\", \"mirror_log\":\"\", \"copy_percent\":\"\", \"convert_lv\":\"\"},\n                  {\"lv_name\":\"short\", \"vg_name\":\"vg0\", \"lv_attr\":\"-wi\", \"lv_size\":\"1.00g\", \"pool_lv\":\"\", \"origin\":\"\", \"data_percent\":\"\", \"metadata_percent\":\"\", \"move_pv\":\"\", \"mirror_log\":\"\", \"copy_percent\":\"\", \"convert_lv\":\"\"}\n              ]\n          }\n      ]\n  }\n", "vg0"], "expected": {"big": 1572864, "tiny": 1, "sm": 0, "pool": 95365}}, {"args": ["{\n      \"report\": [\n          {\n              \"lv\": [\n                  {\"lv_name\":\"one\", \"vg_name\":\"vg0\", \"lv_attr\":\"-wi-a-----\", \"lv_size\":\"1.00g\", \"pool_lv\":\"\", \"origin\":\"\", \"data_percent\":\"\", \"metadata_percent\":\"\", \"move_pv\":\"\", \"mirror_log\":\"\", \"copy_percent\":\"\", \"convert_lv\":\"\"}\n              ]\n          },\n          {\n              \"lv\": [\n                  {\"lv_name\":\"two\", \"vg_name\":\"vg0\", \"lv_attr\":\"-wi-a-----\", \"lv_size\":\"2.00g\", \"pool_lv\":\"\", \"origin\":\"\", \"data_percent\":\"\", \"metadata_percent\":\"\", \"move_pv\":\"\", \"mirror_log\":\"\", \"copy_percent\":\"\", \"convert_lv\":\"\"},\n                  {\"lv_name\":\"three\", \"vg_name\":\"vg1\", \"lv_attr\":\"-wi-a-----\", \"lv_size\":\"3.00g\", \"pool_lv\":\"\", \"origin\":\"\", \"data_percent\":\"\", \"metadata_percent\":\"\", \"move_pv\":\"\", \"mirror_log\":\"\", \"copy_percent\":\"\", \"convert_lv\":\"\"}\n              ]\n          },\n          {\n          }\n      ]\n  }\n", "vg0"], "expected": {"one": 1024, "two": 2048}}, {"args": ["{\n      \"report\": [\n          {\n              \"lv\": [\n\n              ]\n          }\n      ]\n  }\n", "vg0"], "expected": {}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 21, 'la21-global-addrs', 1, 'func', 'Глобальные адреса из ip -j addr', 'Вывод команды ip -j addr — JSON-массив объектов-интерфейсов; у каждого есть ifname, operstate и массив addr_info (может отсутствовать), в котором у адреса есть family ("inet" или "inet6"), local, prefixlen и scope. Напишите функцию global_addrs(text, family): text — вывод команды, family — "inet", "inet6" или "any". Верните словарь имя интерфейса → список строк "адрес/префикс" только для адресов со scope "global" нужного семейства ("any" — любого). Интерфейсы с operstate "DOWN" пропускайте, интерфейсы без подходящих адресов в словарь не включайте. Внутри списка сначала адреса inet, потом inet6, внутри семейства — по обычному порядку строк.', 'def global_addrs(text, family):
    pass
', 'Читайте необязательные ключи через .get; для сортировки составьте пары (0 или 1 по семейству, строка).', '{"func": "global_addrs", "tests": [{"args": ["[{\"ifindex\":1,\"ifname\":\"lo\",\"flags\":[\"LOOPBACK\",\"UP\",\"LOWER_UP\"],\"mtu\":1500,\"qdisc\":\"fq_codel\",\"operstate\":\"UNKNOWN\",\"group\":\"default\",\"txqlen\":1000,\"link_type\":\"loopback\",\"address\":\"52:54:00:12:34:01\",\"broadcast\":\"ff:ff:ff:ff:ff:ff\",\"addr_info\":[{\"family\":\"inet\",\"local\":\"127.0.0.1\",\"prefixlen\":8,\"scope\":\"host\",\"label\":\"lo\",\"valid_life_time\":4294967295,\"preferred_life_time\":4294967295},{\"family\":\"inet6\",\"local\":\"::1\",\"prefixlen\":128,\"scope\":\"host\",\"valid_life_time\":4294967295,\"preferred_life_time\":4294967295}]},{\"ifindex\":2,\"ifname\":\"eth0\",\"flags\":[\"BROADCAST\",\"MULTICAST\",\"UP\",\"LOWER_UP\"],\"mtu\":1500,\"qdisc\":\"fq_codel\",\"operstate\":\"UP\",\"group\":\"default\",\"txqlen\":1000,\"link_type\":\"ether\",\"address\":\"52:54:00:12:34:02\",\"broadcast\":\"ff:ff:ff:ff:ff:ff\",\"addr_info\":[{\"family\":\"inet\",\"local\":\"192.0.2.10\",\"prefixlen\":24,\"scope\":\"global\",\"label\":\"eth0\",\"valid_life_time\":4294967295,\"preferred_life_time\":4294967295},{\"family\":\"inet6\",\"local\":\"2001:db8::10\",\"prefixlen\":64,\"scope\":\"global\",\"valid_life_time\":4294967295,\"preferred_life_time\":4294967295},{\"family\":\"inet6\",\"local\":\"fe80::5054:ff:fe12:3402\",\"prefixlen\":64,\"scope\":\"link\",\"valid_life_time\":4294967295,\"preferred_life_time\":4294967295}]}]\n", "any"], "expected": {"eth0": ["192.0.2.10/24", "2001:db8::10/64"]}}, {"args": ["[{\"ifindex\":2,\"ifname\":\"eth0\",\"flags\":[\"BROADCAST\",\"MULTICAST\",\"UP\",\"LOWER_UP\"],\"mtu\":1500,\"qdisc\":\"fq_codel\",\"operstate\":\"UP\",\"group\":\"default\",\"txqlen\":1000,\"link_type\":\"ether\",\"address\":\"52:54:00:12:34:02\",\"broadcast\":\"ff:ff:ff:ff:ff:ff\",\"addr_info\":[{\"family\":\"inet\",\"local\":\"192.0.2.10\",\"prefixlen\":24,\"scope\":\"global\",\"label\":\"eth0\",\"valid_life_time\":4294967295,\"preferred_life_time\":4294967295},{\"family\":\"inet6\",\"local\":\"2001:db8::10\",\"prefixlen\":64,\"scope\":\"global\",\"valid_life_time\":4294967295,\"preferred_life_time\":4294967295}]},{\"ifindex\":3,\"ifname\":\"docker0\",\"flags\":[\"NO-CARRIER\",\"BROADCAST\",\"MULTICAST\",\"UP\"],\"mtu\":1500,\"qdisc\":\"fq_codel\",\"operstate\":\"DOWN\",\"group\":\"default\",\"txqlen\":1000,\"link_type\":\"ether\",\"address\":\"52:54:00:12:34:03\",\"broadcast\":\"ff:ff:ff:ff:ff:ff\",\"addr_info\":[{\"family\":\"inet\",\"local\":\"172.17.0.1\",\"prefixlen\":16,\"scope\":\"global\",\"label\":\"docker0\",\"valid_life_time\":4294967295,\"preferred_life_time\":4294967295}]},{\"ifindex\":4,\"ifname\":\"wg0\",\"flags\":[\"POINTOPOINT\",\"NOARP\",\"UP\",\"LOWER_UP\"],\"mtu\":1500,\"qdisc\":\"fq_codel\",\"operstate\":\"UNKNOWN\",\"group\":\"default\",\"txqlen\":1000,\"link_type\":\"none\",\"address\":\"52:54:00:12:34:04\",\"broadcast\":\"ff:ff:ff:ff:ff:ff\",\"addr_info\":[{\"family\":\"inet\",\"local\":\"10.8.0.2\",\"prefixlen\":32,\"scope\":\"global\",\"label\":\"wg0\",\"valid_life_time\":4294967295,\"preferred_life_time\":4294967295}]}]\n", "inet"], "expected": {"eth0": ["192.0.2.10/24"], "wg0": ["10.8.0.2/32"]}}, {"args": ["[{\"ifindex\":2,\"ifname\":\"eth0\",\"flags\":[\"BROADCAST\",\"MULTICAST\",\"UP\",\"LOWER_UP\"],\"mtu\":1500,\"qdisc\":\"fq_codel\",\"operstate\":\"UP\",\"group\":\"default\",\"txqlen\":1000,\"link_type\":\"ether\",\"address\":\"52:54:00:12:34:02\",\"broadcast\":\"ff:ff:ff:ff:ff:ff\",\"addr_info\":[{\"family\":\"inet\",\"local\":\"192.0.2.10\",\"prefixlen\":24,\"scope\":\"global\",\"label\":\"eth0\",\"valid_life_time\":4294967295,\"preferred_life_time\":4294967295},{\"family\":\"inet6\",\"local\":\"2001:db8::10\",\"prefixlen\":64,\"scope\":\"global\",\"valid_life_time\":4294967295,\"preferred_life_time\":4294967295}]},{\"ifindex\":5,\"ifname\":\"br0\",\"flags\":[\"BROADCAST\",\"MULTICAST\",\"UP\",\"LOWER_UP\"],\"mtu\":1500,\"qdisc\":\"fq_codel\",\"operstate\":\"UP\",\"group\":\"default\",\"txqlen\":1000,\"link_type\":\"ether\",\"address\":\"52:54:00:12:34:05\",\"broadcast\":\"ff:ff:ff:ff:ff:ff\",\"addr_info\":[{\"family\":\"inet\",\"local\":\"10.0.0.10\",\"prefixlen\":24,\"scope\":\"global\",\"label\":\"br0\",\"valid_life_time\":4294967295,\"preferred_life_time\":4294967295},{\"family\":\"inet\",\"local\":\"10.0.0.9\",\"prefixlen\":24,\"scope\":\"global\",\"label\":\"br0\",\"valid_life_time\":4294967295,\"preferred_life_time\":4294967295},{\"family\":\"inet6\",\"local\":\"2001:db8:1::1\",\"prefixlen\":64,\"scope\":\"global\",\"valid_life_time\":4294967295,\"preferred_life_time\":4294967295},{\"family\":\"inet6\",\"local\":\"2001:db8:1::2\",\"prefixlen\":64,\"scope\":\"global\",\"valid_life_time\":4294967295,\"preferred_life_time\":4294967295}]}]\n", "any"], "expected": {"eth0": ["192.0.2.10/24", "2001:db8::10/64"], "br0": ["10.0.0.10/24", "10.0.0.9/24", "2001:db8:1::1/64", "2001:db8:1::2/64"]}}, {"args": ["[{\"ifindex\":2,\"ifname\":\"eth0\",\"flags\":[\"BROADCAST\",\"MULTICAST\",\"UP\",\"LOWER_UP\"],\"mtu\":1500,\"qdisc\":\"fq_codel\",\"operstate\":\"UP\",\"group\":\"default\",\"txqlen\":1000,\"link_type\":\"ether\",\"address\":\"52:54:00:12:34:02\",\"broadcast\":\"ff:ff:ff:ff:ff:ff\",\"addr_info\":[{\"family\":\"inet\",\"local\":\"192.0.2.10\",\"prefixlen\":24,\"scope\":\"global\",\"label\":\"eth0\",\"valid_life_time\":4294967295,\"preferred_life_time\":4294967295},{\"family\":\"inet6\",\"local\":\"2001:db8::10\",\"prefixlen\":64,\"scope\":\"global\",\"valid_life_time\":4294967295,\"preferred_life_time\":4294967295}]},{\"ifindex\":6,\"ifname\":\"veth1\",\"flags\":[\"BROADCAST\",\"MULTICAST\",\"UP\",\"LOWER_UP\"],\"mtu\":1500,\"qdisc\":\"fq_codel\",\"operstate\":\"UP\",\"group\":\"default\",\"txqlen\":1000,\"link_type\":\"ether\",\"address\":\"52:54:00:12:34:06\",\"broadcast\":\"ff:ff:ff:ff:ff:ff\",\"addr_info\":[]}]\n", "inet6"], "expected": {"eth0": ["2001:db8::10/64"]}}, {"args": ["[{\"ifindex\":7,\"ifname\":\"vnet0\",\"flags\":[\"BROADCAST\",\"MULTICAST\",\"UP\",\"LOWER_UP\"],\"mtu\":1500,\"qdisc\":\"fq_codel\",\"operstate\":\"UP\",\"group\":\"default\",\"txqlen\":1000,\"link_type\":\"ether\",\"address\":\"52:54:00:12:34:07\",\"broadcast\":\"ff:ff:ff:ff:ff:ff\",\"addr_info\":[{\"family\":\"inet6\",\"local\":\"fe80::fc54:ff:fe00:1\",\"prefixlen\":64,\"scope\":\"link\",\"valid_life_time\":4294967295,\"preferred_life_time\":4294967295}]}]\n", "any"], "expected": {}}, {"args": ["[]\n", "any"], "expected": {}}, {"args": ["[{\"ifindex\": 9, \"ifname\": \"dummy0\", \"operstate\": \"UP\"}]", "any"], "expected": {}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 21, 'la21-default-gateway', 2, 'func', 'Шлюз по умолчанию из ip -j route', 'Вывод команды ip -j route — JSON-массив маршрутов; у маршрута есть dst и dev, а gateway, metric и flags бывают не всегда. Напишите функцию default_gateway(text): выберите среди маршрутов с dst равным "default" и с ключом gateway тот, чьё значение metric наименьшее (если ключа metric нет, метрика равна 0); маршруты, в flags которых есть "linkdown", не рассматриваются; при равных метриках побеждает маршрут, стоящий в списке раньше. Верните список [gateway, dev] выбранного маршрута или None, если подходящих маршрутов нет.', 'def default_gateway(text):
    pass
', 'Идите по маршрутам один раз, храните лучшую тройку (метрика, шлюз, устройство); строгое «меньше» сохраняет первый при равенстве.', '{"func": "default_gateway", "tests": [{"args": ["[{\"dst\":\"default\",\"gateway\":\"192.0.2.1\",\"protocol\":\"dhcp\",\"prefsrc\":\"192.0.2.10\",\"metric\":100,\"flags\":[],\"dev\":\"eth0\"},{\"dst\":\"192.0.2.0/24\",\"protocol\":\"kernel\",\"scope\":\"link\",\"prefsrc\":\"192.0.2.10\",\"metric\":100,\"flags\":[],\"dev\":\"eth0\"}]\n"], "expected": ["192.0.2.1", "eth0"]}, {"args": ["[{\"dst\":\"192.0.2.0/24\",\"protocol\":\"kernel\",\"scope\":\"link\",\"prefsrc\":\"192.0.2.10\",\"metric\":100,\"flags\":[],\"dev\":\"eth0\"}]\n"], "expected": null}, {"args": ["[]\n"], "expected": null}, {"args": ["[{\"dst\":\"default\",\"gateway\":\"192.168.1.1\",\"protocol\":\"dhcp\",\"metric\":600,\"flags\":[],\"dev\":\"wlan0\"},{\"dst\":\"default\",\"gateway\":\"192.0.2.1\",\"protocol\":\"dhcp\",\"metric\":100,\"flags\":[],\"dev\":\"eth0\"},{\"dst\":\"192.0.2.0/24\",\"protocol\":\"kernel\",\"scope\":\"link\",\"prefsrc\":\"192.0.2.10\",\"metric\":100,\"flags\":[],\"dev\":\"eth0\"}]\n"], "expected": ["192.0.2.1", "eth0"]}, {"args": ["[{\"dst\":\"default\",\"gateway\":\"192.0.2.1\",\"protocol\":\"static\",\"flags\":[],\"dev\":\"eth0\"},{\"dst\":\"default\",\"gateway\":\"192.168.1.1\",\"protocol\":\"dhcp\",\"metric\":600,\"flags\":[],\"dev\":\"wlan0\"}]\n"], "expected": ["192.0.2.1", "eth0"]}, {"args": ["[{\"dst\":\"default\",\"gateway\":\"192.0.2.1\",\"metric\":100,\"flags\":[\"linkdown\"],\"dev\":\"eth0\"},{\"dst\":\"default\",\"gateway\":\"198.51.100.1\",\"metric\":200,\"flags\":[],\"dev\":\"eth1\"}]\n"], "expected": ["198.51.100.1", "eth1"]}, {"args": ["[{\"dst\":\"default\",\"scope\":\"link\",\"flags\":[],\"dev\":\"ppp0\"},{\"dst\":\"default\",\"gateway\":\"192.0.2.1\",\"metric\":50,\"flags\":[],\"dev\":\"eth0\"}]\n"], "expected": ["192.0.2.1", "eth0"]}, {"args": ["[{\"dst\":\"default\",\"gateway\":\"fe80::1\",\"protocol\":\"ra\",\"metric\":1024,\"flags\":[\"pref\",\"medium\"],\"dev\":\"eth0\"},{\"dst\":\"default\",\"gateway\":\"fe80::2\",\"protocol\":\"ra\",\"metric\":1024,\"flags\":[],\"dev\":\"eth1\"}]\n"], "expected": ["fe80::1", "eth0"]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 21, 'la21-crowded-mounts', 3, 'func', 'Заполненные точки монтирования из df -P', 'Вывод df -P — заголовок и по одной строке на файловую систему: Filesystem, число блоков, Used, Available, Capacity (например 53%) и Mounted on. Точка монтирования занимает остаток строки и может содержать пробелы (в том числе несколько подряд). Размер блока написан во втором слове заголовка: 1024-blocks или 512-blocks. Напишите функцию crowded_mounts(text, threshold): верните список пар [точка монтирования, свободно в байтах (Available, умноженное на размер блока)] для строк, у которых Capacity не меньше threshold процентов, отсортированный по Capacity по убыванию, а при равенстве по точке монтирования. Строки, где вместо процента стоит "-", пропускайте; для пустого текста верните пустой список. Имя файловой системы пробелов не содержит.', 'def crowded_mounts(text, threshold):
    pass
', 'line.split(None, 5) оставляет остаток строки нетронутым. Размер блока: int(заголовок.split()[1].split(''-'')[0]).', '{"func": "crowded_mounts", "tests": [{"args": ["Filesystem            1024-blocks     Used Available Capacity Mounted on\n/dev/mapper/rhel-root    17811456  9437184   8374272      53% /\ndevtmpfs                     4096        0      4096       0% /dev\n/dev/sda1                 1038336   905216    133120      88% /boot\n/dev/mapper/vg0-data    104805376 99614720   5190656      96% /srv/My Data\n/dev/sdb1                 2000000  1000000   1000000      50% /mnt/two  spaces\n", 80], "expected": [["/srv/My Data", 5315231744], ["/boot", 136314880]]}, {"args": ["Filesystem            1024-blocks     Used Available Capacity Mounted on\n/dev/mapper/rhel-root    17811456  9437184   8374272      53% /\ndevtmpfs                     4096        0      4096       0% /dev\n/dev/sda1                 1038336   905216    133120      88% /boot\n/dev/mapper/vg0-data    104805376 99614720   5190656      96% /srv/My Data\n/dev/sdb1                 2000000  1000000   1000000      50% /mnt/two  spaces\n", 50], "expected": [["/srv/My Data", 5315231744], ["/boot", 136314880], ["/", 8575254528], ["/mnt/two  spaces", 1024000000]]}, {"args": ["Filesystem            1024-blocks     Used Available Capacity Mounted on\n/dev/mapper/rhel-root    17811456  9437184   8374272      53% /\ndevtmpfs                     4096        0      4096       0% /dev\n/dev/sda1                 1038336   905216    133120      88% /boot\n/dev/mapper/vg0-data    104805376 99614720   5190656      96% /srv/My Data\n/dev/sdb1                 2000000  1000000   1000000      50% /mnt/two  spaces\n", 99], "expected": []}, {"args": ["Filesystem            1024-blocks     Used Available Capacity Mounted on\n/dev/mapper/rhel-root    17811456  9437184   8374272      53% /\ndevtmpfs                     4096        0      4096       0% /dev\n/dev/sda1                 1038336   905216    133120      88% /boot\n/dev/mapper/vg0-data    104805376 99614720   5190656      96% /srv/My Data\n/dev/sdb1                 2000000  1000000   1000000      50% /mnt/two  spaces\n", 0], "expected": [["/srv/My Data", 5315231744], ["/boot", 136314880], ["/", 8575254528], ["/mnt/two  spaces", 1024000000], ["/dev", 4194304]]}, {"args": ["Filesystem     512-blocks    Used Available Capacity Mounted on\n/dev/sda2         2000000 1900000    100000      95% /\n/dev/sda3             400     100       300      25% /home\n", 90], "expected": [["/", 51200000]]}, {"args": ["Filesystem     1024-blocks Used Available Capacity Mounted on\n/dev/sda2             1000  900       100      90% /\nnone                     0    0         0        - /run/lock\n/dev/sdb              1000  900       100      90% /data\n", 0], "expected": [["/", 102400], ["/data", 102400]]}, {"args": ["", 10], "expected": []}, {"args": ["Filesystem     1024-blocks Used Available Capacity Mounted on\n", 0], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 21, 'la21-units-attention', 4, 'func', 'Службы, требующие внимания, из systemctl show', 'Команда systemctl show -p Id -p LoadState ... для нескольких юнитов печатает блоки строк Key=Value, блоки разделены пустой строкой (между блоками может быть и несколько пустых строк). Значение — всё после первого знака =, оно само может содержать =; строки без = игнорируйте. Напишите функцию units_needing_attention(text, restart_limit): верните словарь Id → причина. Причина выбирается по первому подходящему правилу: "not-found", если LoadState равен not-found; "failed", если ActiveState равен failed; "flapping", если число NRestarts (отсутствующее или пустое значение — 0) не меньше restart_limit. Блок без Id пропускайте; остальные юниты в словарь не попадают.', 'def units_needing_attention(text, restart_limit):
    pass
', 're.split(r''\n\s*\n'', text) делит на блоки; line.split(''='', 1) — на ключ и значение.', '{"func": "units_needing_attention", "tests": [{"args": ["Id=sshd.service\nLoadState=loaded\nActiveState=active\nSubState=running\nNRestarts=0\nExecStart={ path=/usr/sbin/sshd ; argv[]=/usr/sbin/sshd -D $SSHD_OPTS ; ignore_errors=no ; start_time=[n/a] ; stop_time=[n/a] ; pid=0 ; code=(null) ; status=0/0 }\n\nId=app.service\nLoadState=loaded\nActiveState=failed\nSubState=failed\nNRestarts=5\nResult=exit-code\n\nId=nosuch.service\nLoadState=not-found\nActiveState=inactive\nSubState=dead\nNRestarts=0\n\nId=vdsmd.service\nLoadState=loaded\nActiveState=activating\nSubState=auto-restart\nNRestarts=4\n\nId=chronyd.service\nLoadState=loaded\nActiveState=active\nSubState=running\nNRestarts=1\n\nId=backup.timer\nLoadState=loaded\nActiveState=active\nSubState=waiting\n", 3], "expected": {"app.service": "failed", "nosuch.service": "not-found", "vdsmd.service": "flapping"}}, {"args": ["Id=sshd.service\nLoadState=loaded\nActiveState=active\nSubState=running\nNRestarts=0\nExecStart={ path=/usr/sbin/sshd ; argv[]=/usr/sbin/sshd -D $SSHD_OPTS ; ignore_errors=no ; start_time=[n/a] ; stop_time=[n/a] ; pid=0 ; code=(null) ; status=0/0 }\n\nId=app.service\nLoadState=loaded\nActiveState=failed\nSubState=failed\nNRestarts=5\nResult=exit-code\n\nId=nosuch.service\nLoadState=not-found\nActiveState=inactive\nSubState=dead\nNRestarts=0\n\nId=vdsmd.service\nLoadState=loaded\nActiveState=activating\nSubState=auto-restart\nNRestarts=4\n\nId=chronyd.service\nLoadState=loaded\nActiveState=active\nSubState=running\nNRestarts=1\n\nId=backup.timer\nLoadState=loaded\nActiveState=active\nSubState=waiting\n", 1], "expected": {"app.service": "failed", "nosuch.service": "not-found", "vdsmd.service": "flapping", "chronyd.service": "flapping"}}, {"args": ["Id=sshd.service\nLoadState=loaded\nActiveState=active\nSubState=running\nNRestarts=0\nExecStart={ path=/usr/sbin/sshd ; argv[]=/usr/sbin/sshd -D $SSHD_OPTS ; ignore_errors=no ; start_time=[n/a] ; stop_time=[n/a] ; pid=0 ; code=(null) ; status=0/0 }\n\nId=app.service\nLoadState=loaded\nActiveState=failed\nSubState=failed\nNRestarts=5\nResult=exit-code\n\nId=nosuch.service\nLoadState=not-found\nActiveState=inactive\nSubState=dead\nNRestarts=0\n\nId=vdsmd.service\nLoadState=loaded\nActiveState=activating\nSubState=auto-restart\nNRestarts=4\n\nId=chronyd.service\nLoadState=loaded\nActiveState=active\nSubState=running\nNRestarts=1\n\nId=backup.timer\nLoadState=loaded\nActiveState=active\nSubState=waiting\n", 10], "expected": {"app.service": "failed", "nosuch.service": "not-found"}}, {"args": ["", 3], "expected": {}}, {"args": ["Id=a.service\nLoadState=loaded\nActiveState=active\nNRestarts=2\n\n\n\nId=b.service\nLoadState=not-found\nActiveState=failed\nNRestarts=9\n", 2], "expected": {"a.service": "flapping", "b.service": "not-found"}}, {"args": ["LoadState=loaded\nActiveState=failed\n", 1], "expected": {}}, {"args": ["Id=x.service\nActiveState=active\nNRestarts=\n", 0], "expected": {"x.service": "flapping"}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 21, 'la21-ssh-argv', 5, 'func', 'Безопасная команда ssh', 'Удалённая сторона получает команду одной строкой и выполняет её оболочкой пользователя, поэтому каждый аргумент надо экранировать. Напишите функцию ssh_argv(host, remote_args), которая возвращает список аргументов для запуска без оболочки: ["ssh", "-o", "BatchMode=yes", host, строка], где строка — remote_args, каждый элемент экранирован и все соединены одним пробелом. Экранирование элемента: непустой элемент из букв a-z A-Z, цифр и символов @ % + = : , . / _ - остаётся как есть; любой другой (включая пустой) берётся в одинарные кавычки, а каждая одинарная кавычка внутри заменяется на ''"''"''. Хост должен иметь вид [пользователь@]имя: пользователь начинается с буквы или _ и состоит из букв, цифр, _ и -; имя начинается с буквы или цифры и состоит из букв, цифр, точек и дефисов. Иначе (в том числе имя вроде -oProxyCommand=...) или если remote_args пуст, верните None.', 'def ssh_argv(host, remote_args):
    pass
', 're.fullmatch для хоста; для элементов можно взять shlex.quote — он делает ровно это, но убедитесь, что понимаете правило.', '{"func": "ssh_argv", "tests": [{"args": ["web1.example.org", ["uptime"]], "expected": ["ssh", "-o", "BatchMode=yes", "web1.example.org", "uptime"]}, {"args": ["root@10.0.0.5", ["ls", "-l", "/srv/my files"]], "expected": ["ssh", "-o", "BatchMode=yes", "root@10.0.0.5", "ls -l ''/srv/my files''"]}, {"args": ["admin@node-2", ["lvs", "--noheadings", "-o", "lv_name,lv_size", "vg0"]], "expected": ["ssh", "-o", "BatchMode=yes", "admin@node-2", "lvs --noheadings -o lv_name,lv_size vg0"]}, {"args": ["web1", ["echo", "a;reboot", "$(id)", "`id`", "x y"]], "expected": ["ssh", "-o", "BatchMode=yes", "web1", "echo ''a;reboot'' ''$(id)'' ''`id`'' ''x y''"]}, {"args": ["web1", ["grep", "it''s", "/var/log/syslog"]], "expected": ["ssh", "-o", "BatchMode=yes", "web1", "grep ''it''\"''\"''s'' /var/log/syslog"]}, {"args": ["web1", ["printf", "%s", "", "tab\there", "ünï"]], "expected": ["ssh", "-o", "BatchMode=yes", "web1", "printf %s '''' ''tab\there'' ''ünï''"]}, {"args": ["-oProxyCommand=touch /tmp/pwned", ["uptime"]], "expected": null}, {"args": ["-J", ["uptime"]], "expected": null}, {"args": ["user@-x", ["uptime"]], "expected": null}, {"args": ["web1;reboot", ["uptime"]], "expected": null}, {"args": ["", ["uptime"]], "expected": null}, {"args": ["web1", []], "expected": null}, {"args": ["_svc@a.b-c.d", ["cat", "/etc/hostname"]], "expected": ["ssh", "-o", "BatchMode=yes", "_svc@a.b-c.d", "cat /etc/hostname"]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 21, 'la21-classify-exit', 6, 'func', 'Что значит этот результат запуска', 'Результат запуска внешней команды бывает двух видов: ["returned", код] (процесс завершился с кодом возврата) и ["raised", имя_исключения] (Питон выбросил исключение). Напишите функцию classify_exit(shell, outcome), где shell — запускали ли команду через оболочку (shell=True). Верните строку: для исключений "missing" (FileNotFoundError), "not-executable" (PermissionError), "timeout" (TimeoutExpired), иначе "error:" и имя исключения. Для кода: 0 даёт "ok"; отрицательный код -N значит смерть от сигнала N и даёт "signal:ИМЯ"; при shell равном True оболочка сообщает 127 для «не найдено» ("missing"), 126 для «не исполняемо» ("not-executable") и 128+N для сигнала N (больше 128, вплоть до 255); всё остальное даёт "failed:" и код. Имя сигнала берите из таблицы 1 SIGHUP, 2 SIGINT, 3 SIGQUIT, 6 SIGABRT, 9 SIGKILL, 11 SIGSEGV, 13 SIGPIPE, 14 SIGALRM, 15 SIGTERM, а для любого другого номера подставьте сам номер (например "signal:34"). Без оболочки 127, 126 и 130 — обычные коды программы.', 'def classify_exit(shell, outcome):
    pass
', 'Сначала исключения, потом код 0, потом отрицательные, потом правила оболочки, в конце failed.', '{"func": "classify_exit", "tests": [{"args": [false, ["returned", 0]], "expected": "ok"}, {"args": [true, ["returned", 0]], "expected": "ok"}, {"args": [false, ["returned", 3]], "expected": "failed:3"}, {"args": [true, ["returned", 3]], "expected": "failed:3"}, {"args": [false, ["returned", 127]], "expected": "failed:127"}, {"args": [true, ["returned", 127]], "expected": "missing"}, {"args": [true, ["returned", 126]], "expected": "not-executable"}, {"args": [false, ["returned", 126]], "expected": "failed:126"}, {"args": [false, ["returned", -9]], "expected": "signal:SIGKILL"}, {"args": [false, ["returned", -15]], "expected": "signal:SIGTERM"}, {"args": [false, ["returned", -34]], "expected": "signal:34"}, {"args": [true, ["returned", 137]], "expected": "signal:SIGKILL"}, {"args": [true, ["returned", 143]], "expected": "signal:SIGTERM"}, {"args": [false, ["returned", 137]], "expected": "failed:137"}, {"args": [true, ["returned", 128]], "expected": "failed:128"}, {"args": [true, ["returned", 200]], "expected": "signal:72"}, {"args": [true, ["returned", 255]], "expected": "signal:127"}, {"args": [false, ["raised", "FileNotFoundError"]], "expected": "missing"}, {"args": [false, ["raised", "PermissionError"]], "expected": "not-executable"}, {"args": [false, ["raised", "TimeoutExpired"]], "expected": "timeout"}, {"args": [true, ["raised", "TimeoutExpired"]], "expected": "timeout"}, {"args": [false, ["raised", "OSError"]], "expected": "error:OSError"}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 21, 'la21-replay', 7, 'func', 'Подставной run для тестов', 'Код, который запускает команды, принимает параметр run и в тестах получает подставной. Напишите функцию replay(script, calls): script — список записей [argv, код, stdout, stderr], calls — список вызовов (каждый — список аргументов). Каждый вызов берёт первую в порядке script ещё не использованную запись с таким же числом аргументов, у которой каждый аргумент равен аргументу вызова или равен "*" (подходит к любому); запись помечается использованной и даёт результат [код, stdout, stderr]. Если подходящей записи нет, результат вызова — None. Верните список [результаты по порядку вызовов, argv неиспользованных записей в порядке script].', 'def replay(script, calls):
    pass
', 'Заведите список флагов «использовано» и для каждого вызова ищите первую подходящую запись.', '{"func": "replay", "tests": [{"args": [[], []], "expected": [[], []]}, {"args": [[[["vgs", "--noheadings", "vg0"], 0, "  vg0\n", ""]], [["vgs", "--noheadings", "vg0"]]], "expected": [[[0, "  vg0\n", ""]], []]}, {"args": [[[["lvs", "vg0"], 0, "first\n", ""], [["lvs", "vg0"], 5, "", "Volume group \"vg0\" not found\n"]], [["lvs", "vg0"], ["lvs", "vg0"], ["lvs", "vg0"]]], "expected": [[[0, "first\n", ""], [5, "", "Volume group \"vg0\" not found\n"], null], []]}, {"args": [[[["lvs", "*"], 0, "any\n", ""], [["lvs", "vg0"], 0, "exact\n", ""]], [["lvs", "vg0"], ["lvs", "vg0"], ["lvs"], ["lvs", "vg0", "-a"]]], "expected": [[[0, "any\n", ""], [0, "exact\n", ""], null, null], []]}, {"args": [[[["ip", "-j", "addr"], 0, "[]\n", ""], [["df", "-Pk", "/"], 0, "x\n", ""], [["systemctl", "show", "*", "-p", "Id"], 0, "Id=a\n", ""]], [["df", "-Pk", "/"], ["systemctl", "show", "sshd", "-p", "Id"]]], "expected": [[[0, "x\n", ""], [0, "Id=a\n", ""]], [["ip", "-j", "addr"]]]}, {"args": [[[["a"], 0, "1", ""], [["a"], 0, "2", ""], [["b"], 1, "", "e"]], [["b"], ["a"]]], "expected": [[[1, "", "e"], [0, "1", ""]], [["a"]]]}, {"args": [[[["lvs", "*", "*"], 0, "ok", ""]], [["lvs", "vg0"], ["lvs", "vg0", "root"], ["lvs", "vg0", "root", "x"]]], "expected": [[null, [0, "ok", ""], null], []]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 21, 'la21-retry-plan', 8, 'func', 'Повторы с таймаутом на поддельных часах', 'Смоделируйте цикл повторов без настоящего времени. outcomes — заготовленные результаты попыток по порядку: ["rc", код, секунды] (команда вернула код через столько секунд) или ["hang"] (команда не завершится никогда). Напишите функцию retry_plan(outcomes, attempts, timeout, base_delay, budget, retry_on). Часы начинаются с 0. Попытка k (с нуля) берёт outcomes[k]; если это "hang" или секунды больше timeout, команду убивают по таймауту: часы идут на timeout, итог попытки — "timeout", и это временный сбой. Иначе часы идут на секунды; код 0 завершает цикл итогом "ok"; ненулевой код — итог "failed", и если он не входит в retry_on, цикл завершается сразу с этим итогом. После временного сбоя, если попытка не последняя, перед следующей спят base_delay * 2**k секунд, но если часы плюс эта пауза превысили бы budget, цикл завершается итогом "budget", а спать не надо. Верните [итог, число сделанных попыток, часы]. Если попытки закончились — итог последней попытки.', 'def retry_plan(outcomes, attempts, timeout, base_delay, budget, retry_on):
    pass
', 'Цикл по k; таймаут проверяйте раньше кода; «transient» — это либо таймаут, либо ненулевой код из retry_on.', '{"func": "retry_plan", "tests": [{"args": [[["rc", 0, 2]], 3, 10, 1, 60, [75]], "expected": ["ok", 1, 2]}, {"args": [[["rc", 75, 1], ["rc", 75, 1], ["rc", 0, 3]], 5, 10, 1, 60, [75]], "expected": ["ok", 3, 8]}, {"args": [[["rc", 75, 1], ["rc", 75, 1], ["rc", 75, 1]], 3, 10, 2, 60, [75]], "expected": ["failed", 3, 9]}, {"args": [[["rc", 2, 1], ["rc", 0, 1]], 5, 10, 1, 60, [75]], "expected": ["failed", 1, 1]}, {"args": [[["hang"], ["hang"], ["hang"], ["hang"]], 4, 5, 1, 60, [75]], "expected": ["timeout", 4, 27]}, {"args": [[["hang"], ["rc", 0, 4]], 3, 5, 3, 60, []], "expected": ["ok", 2, 12]}, {"args": [[["rc", 0, 9], ["rc", 0, 2]], 2, 5, 1, 60, []], "expected": ["ok", 2, 8]}, {"args": [[["rc", 75, 20], ["rc", 75, 20], ["rc", 75, 20]], 3, 30, 4, 50, [75]], "expected": ["budget", 2, 44]}, {"args": [[["rc", 75, 1]], 1, 10, 5, 60, [75]], "expected": ["failed", 1, 1]}, {"args": [[["rc", 1, 0], ["rc", 1, 0], ["rc", 1, 0], ["rc", 0, 0]], 4, 10, 2, 100, [1]], "expected": ["ok", 4, 14]}, {"args": [[["rc", 1, 0], ["rc", 1, 0], ["rc", 1, 0], ["rc", 0, 0]], 3, 10, 2, 100, [1]], "expected": ["failed", 3, 6]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 21, 'la21-mounted-devices', 9, 'func', 'Устройства и их заполнение: lsblk -J + df', 'Вывод lsblk -J — объект {"blockdevices": [...]}; у устройства есть name, type, точки монтирования и необязательный массив children с вложенными устройствами. Точки монтирования лежат либо в списке "mountpoints" (новые версии util-linux; в нём бывает null), либо в одном значении "mountpoint" (строка или null). Напишите функцию mounted_devices(lsblk_text, usage): usage — словарь точка монтирования → процент заполнения из df. Обойдите дерево целиком и верните список [точка, имя, тип, процент] для каждой пары (точка монтирования, устройство); процент берётся из usage, а если точки там нет — None. Точки, начинающиеся с "[" (например "[SWAP]"), и null пропускайте. Одно устройство может встретиться в дереве несколько раз (под разными родителями) — пара (точка, имя) должна попасть в ответ один раз. Отсортируйте результат по точке монтирования, затем по имени.', 'def mounted_devices(lsblk_text, usage):
    pass
', 'Рекурсивный обход children; словарь с ключом (точка, имя) убирает повторы; если ключа "mountpoints" нет, возьмите [d.get(''mountpoint'')].', '{"func": "mounted_devices", "tests": [{"args": ["{\n   \"blockdevices\": [\n      {\n         \"name\": \"sda\",\n         \"maj:min\": \"8:0\",\n         \"rm\": false,\n         \"size\": \"100G\",\n         \"ro\": false,\n         \"type\": \"disk\",\n         \"mountpoints\": [\n            null\n         ],\n         \"children\": [\n            {\n               \"name\": \"sda1\",\n               \"maj:min\": \"8:0\",\n               \"rm\": false,\n               \"size\": \"1G\",\n               \"ro\": false,\n               \"type\": \"part\",\n               \"mountpoints\": [\n                  \"/boot\"\n               ]\n            },\n            {\n               \"name\": \"sda2\",\n               \"maj:min\": \"8:0\",\n               \"rm\": false,\n               \"size\": \"99G\",\n               \"ro\": false,\n               \"type\": \"part\",\n               \"mountpoints\": [\n                  null\n               ],\n               \"children\": [\n                  {\n                     \"name\": \"vg0-root\",\n                     \"maj:min\": \"8:0\",\n                     \"rm\": false,\n                     \"size\": \"50G\",\n                     \"ro\": false,\n                     \"type\": \"lvm\",\n                     \"mountpoints\": [\n                        \"/\"\n                     ]\n                  },\n                  {\n                     \"name\": \"vg0-swap\",\n                     \"maj:min\": \"8:0\",\n                     \"rm\": false,\n                     \"size\": \"8G\",\n                     \"ro\": false,\n                     \"type\": \"lvm\",\n                     \"mountpoints\": [\n                        \"[SWAP]\"\n                     ]\n                  },\n                  {\n                     \"name\": \"vg0-data\",\n                     \"maj:min\": \"8:0\",\n                     \"rm\": false,\n                     \"size\": \"40G\",\n                     \"ro\": false,\n                     \"type\": \"lvm\",\n                     \"mountpoints\": [\n                        \"/srv/My Data\",\n                        \"/mnt/data\"\n                     ]\n                  }\n               ]\n            }\n         ]\n      },\n      {\n         \"name\": \"sdb\",\n         \"maj:min\": \"8:0\",\n         \"rm\": false,\n         \"size\": \"40G\",\n         \"ro\": false,\n         \"type\": \"disk\",\n         \"mountpoints\": [\n            null\n         ],\n         \"children\": [\n            {\n               \"name\": \"sdb1\",\n               \"maj:min\": \"8:0\",\n               \"rm\": false,\n               \"size\": \"40G\",\n               \"ro\": false,\n               \"type\": \"part\",\n               \"mountpoints\": [\n                  null\n               ],\n               \"children\": [\n                  {\n                     \"name\": \"vg0-data\",\n                     \"maj:min\": \"8:0\",\n                     \"rm\": false,\n                     \"size\": \"40G\",\n                     \"ro\": false,\n                     \"type\": \"lvm\",\n                     \"mountpoints\": [\n                        \"/srv/My Data\",\n                        \"/mnt/data\"\n                     ]\n                  }\n               ]\n            }\n         ]\n      },\n      {\n         \"name\": \"sr0\",\n         \"maj:min\": \"8:0\",\n         \"rm\": true,\n         \"size\": \"1024M\",\n         \"ro\": false,\n         \"type\": \"rom\",\n         \"mountpoints\": [\n            null\n         ]\n      }\n   ]\n}\n", {"/": 53, "/boot": 88, "/srv/My Data": 96, "/mnt/data": 96}], "expected": [["/", "vg0-root", "lvm", 53], ["/boot", "sda1", "part", 88], ["/mnt/data", "vg0-data", "lvm", 96], ["/srv/My Data", "vg0-data", "lvm", 96]]}, {"args": ["{\n   \"blockdevices\": [\n      {\n         \"name\": \"sda\",\n         \"maj:min\": \"8:0\",\n         \"rm\": false,\n         \"size\": \"100G\",\n         \"ro\": false,\n         \"type\": \"disk\",\n         \"mountpoints\": [\n            null\n         ],\n         \"children\": [\n            {\n               \"name\": \"sda1\",\n               \"maj:min\": \"8:0\",\n               \"rm\": false,\n               \"size\": \"1G\",\n               \"ro\": false,\n               \"type\": \"part\",\n               \"mountpoints\": [\n                  \"/boot\"\n               ]\n            },\n            {\n               \"name\": \"sda2\",\n               \"maj:min\": \"8:0\",\n               \"rm\": false,\n               \"size\": \"99G\",\n               \"ro\": false,\n               \"type\": \"part\",\n               \"mountpoints\": [\n                  null\n               ],\n               \"children\": [\n                  {\n                     \"name\": \"vg0-root\",\n                     \"maj:min\": \"8:0\",\n                     \"rm\": false,\n                     \"size\": \"50G\",\n                     \"ro\": false,\n                     \"type\": \"lvm\",\n                     \"mountpoints\": [\n                        \"/\"\n                     ]\n                  },\n                  {\n                     \"name\": \"vg0-swap\",\n                     \"maj:min\": \"8:0\",\n                     \"rm\": false,\n                     \"size\": \"8G\",\n                     \"ro\": false,\n                     \"type\": \"lvm\",\n                     \"mountpoints\": [\n                        \"[SWAP]\"\n                     ]\n                  },\n                  {\n                     \"name\": \"vg0-data\",\n                     \"maj:min\": \"8:0\",\n                     \"rm\": false,\n                     \"size\": \"40G\",\n                     \"ro\": false,\n                     \"type\": \"lvm\",\n                     \"mountpoints\": [\n                        \"/srv/My Data\",\n                        \"/mnt/data\"\n                     ]\n                  }\n               ]\n            }\n         ]\n      },\n      {\n         \"name\": \"sdb\",\n         \"maj:min\": \"8:0\",\n         \"rm\": false,\n         \"size\": \"40G\",\n         \"ro\": false,\n         \"type\": \"disk\",\n         \"mountpoints\": [\n            null\n         ],\n         \"children\": [\n            {\n               \"name\": \"sdb1\",\n               \"maj:min\": \"8:0\",\n               \"rm\": false,\n               \"size\": \"40G\",\n               \"ro\": false,\n               \"type\": \"part\",\n               \"mountpoints\": [\n                  null\n               ],\n               \"children\": [\n                  {\n                     \"name\": \"vg0-data\",\n                     \"maj:min\": \"8:0\",\n                     \"rm\": false,\n                     \"size\": \"40G\",\n                     \"ro\": false,\n                     \"type\": \"lvm\",\n                     \"mountpoints\": [\n                        \"/srv/My Data\",\n                        \"/mnt/data\"\n                     ]\n                  }\n               ]\n            }\n         ]\n      },\n      {\n         \"name\": \"sr0\",\n         \"maj:min\": \"8:0\",\n         \"rm\": true,\n         \"size\": \"1024M\",\n         \"ro\": false,\n         \"type\": \"rom\",\n         \"mountpoints\": [\n            null\n         ]\n      }\n   ]\n}\n", {"/": 53}], "expected": [["/", "vg0-root", "lvm", 53], ["/boot", "sda1", "part", null], ["/mnt/data", "vg0-data", "lvm", null], ["/srv/My Data", "vg0-data", "lvm", null]]}, {"args": ["{\n   \"blockdevices\": [\n      {\n         \"name\": \"sda\",\n         \"maj:min\": \"8:0\",\n         \"rm\": false,\n         \"size\": \"100G\",\n         \"ro\": false,\n         \"type\": \"disk\",\n         \"mountpoints\": [\n            null\n         ],\n         \"children\": [\n            {\n               \"name\": \"sda1\",\n               \"maj:min\": \"8:0\",\n               \"rm\": false,\n               \"size\": \"1G\",\n               \"ro\": false,\n               \"type\": \"part\",\n               \"mountpoints\": [\n                  \"/boot\"\n               ]\n            },\n            {\n               \"name\": \"sda2\",\n               \"maj:min\": \"8:0\",\n               \"rm\": false,\n               \"size\": \"99G\",\n               \"ro\": false,\n               \"type\": \"part\",\n               \"mountpoints\": [\n                  null\n               ],\n               \"children\": [\n                  {\n                     \"name\": \"vg0-root\",\n                     \"maj:min\": \"8:0\",\n                     \"rm\": false,\n                     \"size\": \"50G\",\n                     \"ro\": false,\n                     \"type\": \"lvm\",\n                     \"mountpoints\": [\n                        \"/\"\n                     ]\n                  },\n                  {\n                     \"name\": \"vg0-swap\",\n                     \"maj:min\": \"8:0\",\n                     \"rm\": false,\n                     \"size\": \"8G\",\n                     \"ro\": false,\n                     \"type\": \"lvm\",\n                     \"mountpoints\": [\n                        \"[SWAP]\"\n                     ]\n                  },\n                  {\n                     \"name\": \"vg0-data\",\n                     \"maj:min\": \"8:0\",\n                     \"rm\": false,\n                     \"size\": \"40G\",\n                     \"ro\": false,\n                     \"type\": \"lvm\",\n                     \"mountpoints\": [\n                        \"/srv/My Data\",\n                        \"/mnt/data\"\n                     ]\n                  }\n               ]\n            }\n         ]\n      },\n      {\n         \"name\": \"sdb\",\n         \"maj:min\": \"8:0\",\n         \"rm\": false,\n         \"size\": \"40G\",\n         \"ro\": false,\n         \"type\": \"disk\",\n         \"mountpoints\": [\n            null\n         ],\n         \"children\": [\n            {\n               \"name\": \"sdb1\",\n               \"maj:min\": \"8:0\",\n               \"rm\": false,\n               \"size\": \"40G\",\n               \"ro\": false,\n               \"type\": \"part\",\n               \"mountpoints\": [\n                  null\n               ],\n               \"children\": [\n                  {\n                     \"name\": \"vg0-data\",\n                     \"maj:min\": \"8:0\",\n                     \"rm\": false,\n                     \"size\": \"40G\",\n                     \"ro\": false,\n                     \"type\": \"lvm\",\n                     \"mountpoints\": [\n                        \"/srv/My Data\",\n                        \"/mnt/data\"\n                     ]\n                  }\n               ]\n            }\n         ]\n      },\n      {\n         \"name\": \"sr0\",\n         \"maj:min\": \"8:0\",\n         \"rm\": true,\n         \"size\": \"1024M\",\n         \"ro\": false,\n         \"type\": \"rom\",\n         \"mountpoints\": [\n            null\n         ]\n      }\n   ]\n}\n", {}], "expected": [["/", "vg0-root", "lvm", null], ["/boot", "sda1", "part", null], ["/mnt/data", "vg0-data", "lvm", null], ["/srv/My Data", "vg0-data", "lvm", null]]}, {"args": ["{\n   \"blockdevices\": [\n      {\n         \"name\": \"vda\",\n         \"maj:min\": \"8:0\",\n         \"rm\": false,\n         \"size\": \"20G\",\n         \"ro\": false,\n         \"type\": \"disk\",\n         \"mountpoint\": null,\n         \"children\": [\n            {\n               \"name\": \"vda1\",\n               \"maj:min\": \"8:0\",\n               \"rm\": false,\n               \"size\": \"19G\",\n               \"ro\": false,\n               \"type\": \"part\",\n               \"mountpoint\": \"/\"\n            },\n            {\n               \"name\": \"vda2\",\n               \"maj:min\": \"8:0\",\n               \"rm\": false,\n               \"size\": \"1G\",\n               \"ro\": false,\n               \"type\": \"part\",\n               \"mountpoint\": \"[SWAP]\"\n            }\n         ]\n      },\n      {\n         \"name\": \"vdb\",\n         \"maj:min\": \"8:0\",\n         \"rm\": false,\n         \"size\": \"10G\",\n         \"ro\": false,\n         \"type\": \"disk\",\n         \"mountpoint\": \"/data\"\n      }\n   ]\n}\n", {"/": 12, "/data": 1}], "expected": [["/", "vda1", "part", 12], ["/data", "vdb", "disk", 1]]}, {"args": ["{\n   \"blockdevices\": [\n      {\n         \"name\": \"vda\",\n         \"maj:min\": \"8:0\",\n         \"rm\": false,\n         \"size\": \"20G\",\n         \"ro\": false,\n         \"type\": \"disk\",\n         \"mountpoint\": null,\n         \"children\": [\n            {\n               \"name\": \"vda1\",\n               \"maj:min\": \"8:0\",\n               \"rm\": false,\n               \"size\": \"19G\",\n               \"ro\": false,\n               \"type\": \"part\",\n               \"mountpoint\": \"/\"\n            },\n            {\n               \"name\": \"vda2\",\n               \"maj:min\": \"8:0\",\n               \"rm\": false,\n               \"size\": \"1G\",\n               \"ro\": false,\n               \"type\": \"part\",\n               \"mountpoint\": \"[SWAP]\"\n            }\n         ]\n      },\n      {\n         \"name\": \"vdb\",\n         \"maj:min\": \"8:0\",\n         \"rm\": false,\n         \"size\": \"10G\",\n         \"ro\": false,\n         \"type\": \"disk\",\n         \"mountpoint\": \"/data\"\n      }\n   ]\n}\n", {"/data": 99, "/other": 5}], "expected": [["/", "vda1", "part", null], ["/data", "vdb", "disk", 99]]}, {"args": ["{\n   \"blockdevices\": []\n}\n", {"/": 1}], "expected": []}, {"args": ["{\n   \"blockdevices\": [\n      {\n         \"name\": \"loop0\",\n         \"maj:min\": \"8:0\",\n         \"rm\": false,\n         \"size\": \"60M\",\n         \"ro\": false,\n         \"type\": \"loop\",\n         \"mountpoints\": [\n            \"/snap/core/1\"\n         ]\n      }\n   ]\n}\n", {"/snap/core/1": 100}], "expected": [["/snap/core/1", "loop0", "loop", 100]]}]}');
